using System.Linq;
class CosmosQuery
{
    // EF Core 9 Cosmos: sync I/O (e.g. ToList()) now throws at runtime.
    // All queries must use async equivalents.
    async Task FindProducts(ProductContext ctx)
    {
        // Direct Cosmos SQL — safe because we preserved "Discriminator" as the
        // discriminator property name via HasDiscriminator<string>("Discriminator")
        // in OnModelCreating. Without that, EF Core 9 defaults to "$type" and
        // these queries would return zero results against existing documents.
        var sql = "SELECT * FROM c WHERE c.Discriminator = 'Product' AND c.Sku = @sku";

        var products = await ctx.Products.Where(p => p.Sku == "ABC").ToListAsync();
    }
}

